<?php
declare(strict_types=1);
namespace EPejabat\Core;
final class ProfileSummary {
 private static function card(string $title,array $values):string {
  $h='<section class="card"><h2>'.Support::escape($title).'</h2><dl>';$count=0;foreach($values as $label=>$value){if($value===null||$value==='')continue;$h.='<dt>'.Support::escape((string)$label).'</dt><dd>'.Support::escape((string)$value).'</dd>';$count++;}return $h.'</dl>'.(!$count?'<p class="profile-summary-note">Belum diisi.</p>':'').'</section>';
 }
 public static function render(\PDO $p,int $actor,int $staff):string {
  $r=Staff::get($p,$actor,$staff);$self=(int)($r['user_id']??0)===$actor;$org=$r['organisation_id']===null?null:(int)$r['organisation_id'];$x=RegistrationMaster::profileReady($p)?RegistrationMaster::extendedProfile($p,$actor,$staff):[];$e=fn($v)=>Support::escape((string)$v);$url='/profile?id='.$staff;
  $h='<section class="welcome-panel"><div><p class="eyebrow">DASHBOARD PROFIL STAF</p><h2>'.$e($r['full_name']).'</h2><p>Ringkasan maklumat profil sedia ada.</p></div></section><nav class="profile-summary-actions" aria-label="Tindakan profil">';
  if($self||Authorization::allowed($p,$actor,'core.staff.manage',$org))$h.='<a class="button" href="'.$url.'&amp;edit=1">Kemaskini Profil</a>';
  $h.='<a href="/dashboard">Dashboard</a></nav><div class="profile-summary-grid">';$contact=RegistrationMaster::contact($p,$actor,$staff);
  $h.=self::card('Maklumat Peribadi',['Nama penuh'=>$r['full_name'],'Staff ID'=>$r['identity_uuid'],'Status akaun'=>$r['user_id']?($r['is_active']?'Aktif':'Tidak aktif'):'Belum diaktifkan','Telefon bimbit'=>$self?$r['phone']??null:null,'Telefon alternatif'=>$contact['alternative_phone']??null,'WhatsApp'=>$contact['whatsapp_number']??null,'Kemaskini terakhir'=>$x['updated_at']??null]);
  $emails=[];if($self){$emails['E-mel login utama']=$r['email']??null;$emails['Status pengesahan login']=!empty($r['email_verified_at'])?'Disahkan':'Belum disahkan';foreach($x['emails']??[] as $c)$emails[($c['email_type']==='official'?'E-mel rasmi':'E-mel alternatif').' #'.$c['id']]=$c['email'].' · '.$c['status'];}elseif($r['official_email'])$emails['E-mel registry']=$r['official_email'];$h.=self::card('E-mel & Hubungan',$emails);
  $lookup=fn($id)=>$id?Database::query($p,'SELECT name FROM organisations WHERE id=?',[$id])->fetchColumn():null;
  $h.=self::card('Penempatan Rasmi',['Organisasi'=>$lookup($r['organisation_id']),'Fasiliti'=>$lookup($r['facility_id']),'Unit'=>$lookup($r['unit_id']),'Alamat rekod'=>$r['contact_address']??null]);
  if($self){$w=$x['workplace']??[];$fields=['Tempat kerja (deklarasi)'=>$lookup($w['physical_workplace_id']??null),'Organisasi pelaporan (deklarasi)'=>$lookup($w['reporting_organisation_id']??null)];foreach(['line1'=>'Alamat','line2'=>'Alamat tambahan','street'=>'Jalan / taman','postcode'=>'Poskod','city'=>'Bandar','state'=>'Negeri'] as $key=>$label)$fields[$label]=$w[$key]??null;$h.=self::card('Alamat Tempat Kerja — Deklarasi',$fields);}
  $official=[];foreach(['profession'=>'Profesion','position'=>'Skim / jawatan','grade'=>'Gred hakiki','employment_status'=>'Status perkhidmatan'] as $key=>$label)$official[$label]=$r[$key.'_id']?Database::query($p,'SELECT name FROM master_data WHERE id=?',[$r[$key.'_id']])->fetchColumn():null;$official['Jawatan hakiki']=$r['job_title']??null;$h.=self::card('Perkhidmatan Semasa',$official);
  foreach(['verified_professional'=>'Profesional — Disahkan','professional'=>'Profesional — Deklarasi / Permohonan'] as $key=>$title){$v=$x[$key]??[];if(!$v)continue;$fields=[];foreach(['profession'=>'Profesion','position'=>'Skim','grade'=>'Gred hakiki','speciality'=>'Kepakaran','subspeciality'=>'Subkepakaran','administrative_position'=>'Jawatan pentadbiran','top_grade'=>'JUSA / Khas / Turus'] as $field=>$label){$table=in_array($field,['profession','position','grade'],true)?'master_data':'professional_master_catalog';$id=$v[$field.'_id']??null;$fields[$label]=$id?Database::query($p,'SELECT name FROM '.$table.' WHERE id=?',[$id])->fetchColumn():null;}$fields['Tahap kepakaran']=['SPECIALIST'=>'Pakar','CONSULTANT'=>'Pakar Perunding','NONE'=>'Tiada'][$v['specialist_level']??'NONE']??null;foreach(['substantive_position'=>'Jawatan hakiki','acting_grade'=>'Gred memangku','kup_grade'=>'Gred KUP'] as $field=>$label)$fields[$label]=$v[$field]??null;if($key==='professional')$fields['Status']=$x['status']??'SELF_DECLARED';$h.=self::card($title,$fields);}
  if($self&&!empty($x['residential'])){$home=[];foreach(['line1'=>'Alamat','line2'=>'Alamat tambahan','street'=>'Jalan / taman','postcode'=>'Poskod','city'=>'Bandar','state'=>'Negeri'] as $key=>$label)$home[$label]=$x['residential'][$key]??null;$h.=self::card('Alamat Kediaman — Untuk Pemilik Profil Sahaja',$home);}
  return $h.'</div><p class="profile-summary-note">Maklumat yang belum diisi tidak dipaparkan. Deklarasi tidak menggantikan maklumat rasmi yang telah disahkan.</p>';
 }
}
